import React, { useRef, useEffect, useCallback, useState } from 'react';

// ─── 3D math helpers ────────────────────────────────────────────────────────
const rotateX = ([x, y, z], a) => [x, y * Math.cos(a) - z * Math.sin(a), y * Math.sin(a) + z * Math.cos(a)];
const rotateY = ([x, y, z], a) => [x * Math.cos(a) + z * Math.sin(a), y, -x * Math.sin(a) + z * Math.cos(a)];
const rotateZ = ([x, y, z], a) => [x * Math.cos(a) - y * Math.sin(a), x * Math.sin(a) + y * Math.cos(a), z];

const project = ([x, y, z], size, fov = 400) => {
  const scale = fov / (fov + z);
  return { x: x * scale + size / 2, y: y * scale + size / 2, scale };
};

// ─── Icosahedron geometry ───────────────────────────────────────────────────
const PHI = (1 + Math.sqrt(5)) / 2;
const RAW_VERTS = [
  [-1, PHI, 0], [1, PHI, 0], [-1, -PHI, 0], [1, -PHI, 0],
  [0, -1, PHI], [0, 1, PHI], [0, -1, -PHI], [0, 1, -PHI],
  [PHI, 0, -1], [PHI, 0, 1], [-PHI, 0, -1], [-PHI, 0, 1],
];
const EDGES = [
  [0, 11], [0, 5], [0, 1], [0, 7], [0, 10],
  [1, 5], [1, 9], [1, 8], [1, 7],
  [2, 3], [2, 4], [2, 11], [2, 10], [2, 6],
  [3, 4], [3, 9], [3, 8], [3, 6],
  [4, 5], [4, 9], [4, 11],
  [5, 9], [5, 11],
  [6, 7], [6, 8], [6, 10],
  [7, 8], [7, 10],
  [8, 9],
  [10, 11],
];

// Normalize vertices to unit sphere
const norm = Math.sqrt(1 + PHI * PHI);
const VERTICES = RAW_VERTS.map(([x, y, z]) => [x / norm, y / norm, z / norm]);

export default function InteractivePolyhedron({ size = 280 }) {
  const canvasRef = useRef(null);
  const animRef = useRef(null);
  const rotation = useRef({ x: 0.4, y: 0.6, z: 0 });
  const velocity = useRef({ x: 0.003, y: 0.005, z: 0.001 });
  const dragging = useRef(false);
  const lastMouse = useRef({ x: 0, y: 0 });
  const [hovered, setHovered] = useState(false);

  const radius = size * 0.34;

  const draw = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio || 1;
    canvas.width = size * dpr;
    canvas.height = size * dpr;
    ctx.scale(dpr, dpr);
    ctx.clearRect(0, 0, size, size);

    // Apply rotation to every vertex
    const transformed = VERTICES.map((v) => {
      let p = v.map((c) => c * radius);
      p = rotateX(p, rotation.current.x);
      p = rotateY(p, rotation.current.y);
      p = rotateZ(p, rotation.current.z);
      return p;
    });

    const projected = transformed.map((v) => project(v, size));

    // Draw edges
    for (const [a, b] of EDGES) {
      const pa = projected[a];
      const pb = projected[b];
      const avgScale = (pa.scale + pb.scale) / 2;
      const alpha = 0.12 + avgScale * 0.18;
      ctx.beginPath();
      ctx.moveTo(pa.x, pa.y);
      ctx.lineTo(pb.x, pb.y);
      ctx.strokeStyle = `rgba(167, 139, 250, ${alpha})`;
      ctx.lineWidth = 1.2 * avgScale;
      ctx.stroke();
    }

    // Draw vertices
    for (const p of projected) {
      const r = 2 + p.scale * 2.5;
      const alpha = 0.3 + p.scale * 0.5;

      // Glow
      const glow = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, r * 3);
      glow.addColorStop(0, `rgba(139, 92, 246, ${alpha * 0.5})`);
      glow.addColorStop(1, 'rgba(139, 92, 246, 0)');
      ctx.beginPath();
      ctx.arc(p.x, p.y, r * 3, 0, Math.PI * 2);
      ctx.fillStyle = glow;
      ctx.fill();

      // Core dot
      ctx.beginPath();
      ctx.arc(p.x, p.y, r, 0, Math.PI * 2);
      ctx.fillStyle = `rgba(196, 181, 253, ${alpha})`;
      ctx.fill();
    }
  }, [size, radius]);

  const animate = useCallback(() => {
    if (!dragging.current) {
      rotation.current.x += velocity.current.x;
      rotation.current.y += velocity.current.y;
      rotation.current.z += velocity.current.z;
    }
    draw();
    animRef.current = requestAnimationFrame(animate);
  }, [draw]);

  useEffect(() => {
    animRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(animRef.current);
  }, [animate]);

  // ─── Mouse interaction ──────────────────────────────────────────────────
  const handlePointerDown = (e) => {
    dragging.current = true;
    lastMouse.current = { x: e.clientX, y: e.clientY };
    e.currentTarget.setPointerCapture(e.pointerId);
  };

  const handlePointerMove = (e) => {
    if (!dragging.current) return;
    const dx = e.clientX - lastMouse.current.x;
    const dy = e.clientY - lastMouse.current.y;
    rotation.current.y += dx * 0.008;
    rotation.current.x += dy * 0.008;
    lastMouse.current = { x: e.clientX, y: e.clientY };
  };

  const handlePointerUp = () => {
    dragging.current = false;
  };

  return (
    <canvas
      ref={canvasRef}
      width={size}
      height={size}
      className={`interactive-polyhedron ${hovered ? 'interactive-polyhedron--hovered' : ''}`}
      style={{ width: size, height: size, touchAction: 'none' }}
      onPointerDown={handlePointerDown}
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerLeave={() => { dragging.current = false; setHovered(false); }}
      onPointerEnter={() => setHovered(true)}
    />
  );
}
